def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    nonbg = Counter({v:n for v,n in counts.items() if v != bg})
    marker = nonbg.most_common(1)[0][0]
    # The colored exemplar is the longest straight run of non-background,
    # non-marker cells. It may be horizontal or vertical.
    best = None
    for dr, dc in ((0,1),(1,0)):
        for r in range(h):
            for c in range(w):
                pr, pc = r-dr, c-dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] != bg and grid[pr][pc] != marker:
                    continue
                rr, cc = r, c
                vals=[]
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] != bg and grid[rr][cc] != marker:
                    vals.append(grid[rr][cc]); rr += dr; cc += dc
                if len(vals) >= 2 and (best is None or len(vals) > len(best[0])):
                    best=(vals,dr,dc)
    if best is None:
        return [row[:] for row in grid]
    pattern, dr, dc = best
    out=[row[:] for row in grid]
    off=len(pattern)//2
    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker:
                for i,color in enumerate(pattern):
                    rr=r+(i-off)*dr; cc=c+(i-off)*dc
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc]=color
    return out
